package com.portfolio.employee.api;
import com.portfolio.employee.domain.Employee; import com.portfolio.employee.service.EmployeeService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/employees") public class EmployeeController { private final EmployeeService service; public EmployeeController(EmployeeService service){this.service=service;} @GetMapping Page<Employee> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return service.list(PageRequest.of(page,Math.min(size,100),Sort.by("id").descending()));} @GetMapping("/{id}") Employee get(@PathVariable long id){return service.get(id);} @PostMapping ResponseEntity<Employee> create(@Valid @RequestBody EmployeeRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PutMapping("/{id}") Employee update(@PathVariable long id,@Valid @RequestBody EmployeeRequest r){return service.update(id,r);} @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable long id){service.delete(id);return ResponseEntity.noContent().build();} }